-- ---------------------------------------------------------------
-- 4. BASIC DATA VALIDATION
-- ---------------------------------------------------------------
SELECT COUNT(*) AS total_customers FROM customers;
SELECT COUNT(*) AS total_products FROM products;
SELECT COUNT(*) AS total_orders FROM orders;
SELECT COUNT(*) AS total_order_items FROM order_items;
SELECT COUNT(*) AS total_payments FROM payments;

-- Check order status distribution
SELECT status, COUNT(*) AS order_count
FROM orders
GROUP BY status
ORDER BY order_count DESC;

-- ---------------------------------------------------------------
-- 5. CORE BUSINESS KPIs
-- ---------------------------------------------------------------
-- Total revenue from completed orders
SELECT ROUND(SUM(total_amount), 2) AS total_revenue
FROM orders
WHERE status = 'COMPLETED';

-- Total completed orders
SELECT COUNT(*) AS total_completed_orders
FROM orders
WHERE status = 'COMPLETED';

-- Average completed order value
SELECT ROUND(AVG(total_amount), 2) AS average_order_value
FROM orders
WHERE status = 'COMPLETED';

-- Cancelled and pending orders
SELECT
    SUM(status = 'CANCELLED') AS cancelled_orders,
    SUM(status = 'PENDING') AS pending_orders
FROM orders;

-- ---------------------------------------------------------------
-- 6. SALES BY MONTH
-- ---------------------------------------------------------------
SELECT
    DATE_FORMAT(order_date, '%Y-%m') AS sales_month,
    COUNT(*) AS completed_orders,
    ROUND(SUM(total_amount), 2) AS monthly_sales
FROM orders
WHERE status = 'COMPLETED'
GROUP BY DATE_FORMAT(order_date, '%Y-%m')
ORDER BY sales_month;

-- ---------------------------------------------------------------
-- 7. SALES BY CATEGORY
-- ---------------------------------------------------------------
SELECT
    p.category,
    ROUND(SUM(oi.quantity * oi.unit_price), 2) AS category_sales,
    SUM(oi.quantity) AS units_sold
FROM order_items oi
JOIN orders o ON o.order_id = oi.order_id
JOIN products p ON p.product_id = oi.product_id
WHERE o.status = 'COMPLETED'
GROUP BY p.category
ORDER BY category_sales DESC;

-- ---------------------------------------------------------------
-- 8. TOP PRODUCTS
-- ---------------------------------------------------------------
SELECT
    p.product_id,
    p.product_name,
    p.category,
    SUM(oi.quantity) AS units_sold,
    ROUND(SUM(oi.quantity * oi.unit_price), 2) AS product_sales
FROM order_items oi
JOIN orders o ON o.order_id = oi.order_id
JOIN products p ON p.product_id = oi.product_id
WHERE o.status = 'COMPLETED'
GROUP BY p.product_id, p.product_name, p.category
ORDER BY product_sales DESC
LIMIT 10;

-- ---------------------------------------------------------------
-- 9. CUSTOMER PERFORMANCE
-- ---------------------------------------------------------------
SELECT
    c.customer_id,
    c.name,
    c.city,
    COUNT(o.order_id) AS completed_orders,
    ROUND(SUM(o.total_amount), 2) AS total_spent,
    ROUND(AVG(o.total_amount), 2) AS average_order_value
FROM customers c
JOIN orders o ON o.customer_id = c.customer_id
WHERE o.status = 'COMPLETED'
GROUP BY c.customer_id, c.name, c.city
ORDER BY total_spent DESC
LIMIT 10;

-- ---------------------------------------------------------------
-- 10. SALES BY CITY
-- ---------------------------------------------------------------
SELECT
    c.city,
    COUNT(o.order_id) AS completed_orders,
    ROUND(SUM(o.total_amount), 2) AS total_sales
FROM customers c
JOIN orders o ON o.customer_id = c.customer_id
WHERE o.status = 'COMPLETED'
GROUP BY c.city
ORDER BY total_sales DESC;

-- ---------------------------------------------------------------
-- 11. REPEAT CUSTOMERS
-- ---------------------------------------------------------------
SELECT
    c.customer_id,
    c.name,
    COUNT(o.order_id) AS completed_orders,
    ROUND(SUM(o.total_amount), 2) AS total_spent
FROM customers c
JOIN orders o ON o.customer_id = c.customer_id
WHERE o.status = 'COMPLETED'
GROUP BY c.customer_id, c.name
HAVING COUNT(o.order_id) > 1
ORDER BY completed_orders DESC, total_spent DESC;

-- Repeat-customer summary
SELECT
    COUNT(*) AS repeat_customers
FROM (
    SELECT customer_id
    FROM orders
    WHERE status = 'COMPLETED'
    GROUP BY customer_id
    HAVING COUNT(*) > 1
) AS repeat_list;

-- ---------------------------------------------------------------
-- 12. ORDER STATUS ANALYSIS
-- ---------------------------------------------------------------
SELECT
    status,
    COUNT(*) AS order_count,
    ROUND(SUM(total_amount), 2) AS order_value
FROM orders
GROUP BY status
ORDER BY order_count DESC;

-- ---------------------------------------------------------------
-- 13. PAYMENT ANALYSIS
-- ---------------------------------------------------------------
SELECT
    payment_status,
    COUNT(*) AS payment_count,
    ROUND(SUM(amount), 2) AS payment_amount
FROM payments
GROUP BY payment_status
ORDER BY payment_count DESC;

SELECT
    o.status AS order_status,
    p.payment_status,
    COUNT(*) AS transaction_count,
    ROUND(SUM(p.amount), 2) AS amount
FROM orders o
JOIN payments p ON p.order_id = o.order_id
GROUP BY o.status, p.payment_status
ORDER BY o.status, transaction_count DESC;

-- ---------------------------------------------------------------
-- 14. INVENTORY ANALYSIS
-- ---------------------------------------------------------------
SELECT
    product_id,
    product_name,
    category,
    stock,
    price
FROM products
ORDER BY stock ASC
LIMIT 10;

SELECT
    category,
    SUM(stock) AS total_stock,
    ROUND(AVG(price), 2) AS average_price
FROM products
GROUP BY category
ORDER BY total_stock DESC;

-- ---------------------------------------------------------------
-- 15. USEFUL VIEWS FOR POWER BI / REPORTING
-- ---------------------------------------------------------------
DROP VIEW IF EXISTS vw_completed_sales;
CREATE VIEW vw_completed_sales AS
SELECT
    o.order_id,
    o.order_date,
    o.customer_id,
    c.name AS customer_name,
    c.city,
    o.total_amount
FROM orders o
JOIN customers c ON c.customer_id = o.customer_id
WHERE o.status = 'COMPLETED';

DROP VIEW IF EXISTS vw_monthly_sales;
CREATE VIEW vw_monthly_sales AS
SELECT
    DATE_FORMAT(order_date, '%Y-%m') AS sales_month,
    COUNT(*) AS completed_orders,
    ROUND(SUM(total_amount), 2) AS total_sales,
    ROUND(AVG(total_amount), 2) AS average_order_value
FROM orders
WHERE status = 'COMPLETED'
GROUP BY DATE_FORMAT(order_date, '%Y-%m');

DROP VIEW IF EXISTS vw_product_performance;
CREATE VIEW vw_product_performance AS
SELECT
    p.product_id,
    p.product_name,
    p.category,
    SUM(oi.quantity) AS units_sold,
    ROUND(SUM(oi.quantity * oi.unit_price), 2) AS sales
FROM order_items oi
JOIN orders o ON o.order_id = oi.order_id
JOIN products p ON p.product_id = oi.product_id
WHERE o.status = 'COMPLETED'
GROUP BY p.product_id, p.product_name, p.category;

DROP VIEW IF EXISTS vw_customer_performance;
CREATE VIEW vw_customer_performance AS
SELECT
    c.customer_id,
    c.name,
    c.city,
    COUNT(o.order_id) AS completed_orders,
    ROUND(SUM(o.total_amount), 2) AS total_spent,
    ROUND(AVG(o.total_amount), 2) AS average_order_value
FROM customers c
JOIN orders o ON o.customer_id = c.customer_id
WHERE o.status = 'COMPLETED'
GROUP BY c.customer_id, c.name, c.city;

-- Example: views ready for Power BI
SELECT * FROM vw_monthly_sales ORDER BY sales_month;
SELECT * FROM vw_product_performance ORDER BY sales DESC LIMIT 10;
SELECT * FROM vw_customer_performance ORDER BY total_spent DESC LIMIT 10;

